func dividir(a, b float64) (float64, error) {
    if b == 0 {
        return 0, fmt.Errorf("divisão por zero")
    }
    return a / b, nil
}

func somarTudo(nums ...int) int {
    total := 0
    for _, n := range nums { total += n }
    return total
}

